46	pub fn random_segment(path: &Path, opnum: SeqNumberType, num_vectors: u64, dim: usize) -> Segment {
47	    let mut id_gen = PointIdGenerator::default();
48	    let mut segment = build_simple_segment(path, dim, Distance::Dot).unwrap();
49	    let mut rnd = rand::rng();
50	    let payload_key = "number";
51	    let hw_counter = HardwareCounterCell::new();
52	    for _ in 0..num_vectors {
53	        let random_vector: Vec<_> = (0..dim).map(|_| rnd.random_range(0.0..1.0)).collect();
54	        let point_id: PointIdType = id_gen.unique();
55	        let payload_value = rnd.random_range(1..1_000);
56	        let payload: Payload = payload_json! {payload_key: vec![payload_value]};
57	        segment
58	            .upsert_point(
59	                opnum,
60	                point_id,
61	                only_default_vector(&random_vector),
62	                &hw_counter,
63	            )
64	            .unwrap();
65	        segment
66	            .set_payload(opnum, point_id, &payload, &None, &hw_counter)
67	            .unwrap();
68	    }
69	    segment
70	}
