926	    pub fn find_duplicated_points(&self) -> AHashMap<SegmentId, Vec<PointIdType>> {
927	        struct DedupPoint {
928	            segment_id: SegmentId,
929	            point_id: PointIdType,
930	            version: Option<SeqNumberType>,
931	        }
932	
933	        let segments = self
934	            .iter()
935	            .map(|(segment_id, locked_segment)| (segment_id, locked_segment.get()))
936	            .collect::<Vec<_>>();
937	        let locked_segments = segments
938	            .iter()
939	            .map(|(segment_id, locked_segment)| (*segment_id, locked_segment.read()))
940	            .collect::<BTreeMap<_, _>>();
941	
942	        // Iterator produces groups of points by point ID
943	        let point_group_iter = locked_segments
944	            .iter()
945	            .map(|(&segment_id, locked_segment)| {
946	                locked_segment
947	                    .iter_points()
948	                    .map(move |point_id| DedupPoint {
949	                        segment_id,
950	                        point_id,
951	                        version: None,
952	                    })
953	            })
954	            .kmerge_by(|a, b| a.point_id < b.point_id)
955	            .chunk_by(|entry| entry.point_id);
956	
957	        let mut points = Vec::new();
958	        let mut points_to_remove: AHashMap<SegmentId, Vec<PointIdType>> = AHashMap::new();
959	
960	        for (point_id, group_iter) in &point_group_iter {
961	            // Fill buffer with points of current chunk, need at least 2 points to deduplicate
962	            points.clear();
963	            points.extend(group_iter);
964	            if points.len() < 2 {
965	                continue;
966	            }
967	
968	            // Enrich with point version
969	            for dedup_point in &mut points {
970	                dedup_point.version =
971	                    locked_segments[&dedup_point.segment_id].point_version(point_id);
972	            }
973	
974	            // Sort points from highest to lowest version
975	            points.sort_unstable_by_key(|p| Reverse(p.version));
976	
977	            // Keep the first point, remove all others which are older
978	            for &DedupPoint {
979	                segment_id,
980	                point_id,
981	                version,
982	            } in &points[1..]
983	            {
984	                log::trace!(
985	                    "Selected point {point_id} in segment {segment_id} for deduplication (version {version:?} versus {:?} in segment {})",
986	                    points[0].version,
987	                    points[0].segment_id,
988	                );
989	                points_to_remove
990	                    .entry(segment_id)
991	                    .or_default()
992	                    .push(point_id);
993	            }
994	        }
995	
996	        points_to_remove
997	    }
998	}
